// Auth: shared secret header — must match env $env.INBOUND_WEBHOOK_TOKEN
const expected = $env.INBOUND_WEBHOOK_TOKEN;
const given = $input.first().json.headers?.['x-inbound-token'] || '';
if (!expected || given !== expected) {
  throw new Error('unauthorized');
}
return $input.first().json;

// Resolve `source` string to Krayin IDs and build webhook payload.
// Source names below MUST exist in the Krayin lead_sources table.
// See docs/krayin-ids-reference.md for IDs.

const SOURCE_MAP = {
  contact_form:           { source_id: 3,  pipeline_id: 4, stage_id: 13, type_id: 1 },
  scope_builder:          { source_id: 6,  pipeline_id: 4, stage_id: 13, type_id: 3 },
  scope_builder_quiz:     { source_id: 7,  pipeline_id: 4, stage_id: 13, type_id: 3 },
  adhics_readiness_quiz:  { source_id: 8,  pipeline_id: 4, stage_id: 13, type_id: 3, icp_segment_option_id: 1 },
  iso27001_gap_quiz:      { source_id: 9,  pipeline_id: 4, stage_id: 13, type_id: 3, icp_segment_option_id: 2 },
  newsletter:             { source_id: 10, pipeline_id: 4, stage_id: 13, type_id: 1 },
  waitlist:               { source_id: 3,  pipeline_id: 4, stage_id: 13, type_id: 4 },
  partners:               { source_id: 3,  pipeline_id: 4, stage_id: 13, type_id: 1 },
  linkedin_manoj:         { source_id: 11, pipeline_id: 4, stage_id: 13, type_id: 1 },
  linkedin_nelson:        { source_id: 12, pipeline_id: 4, stage_id: 13, type_id: 1 },
  linkedin_vinoth:        { source_id: 13, pipeline_id: 4, stage_id: 13, type_id: 1 },
  cold_email_manoj:       { source_id: 14, pipeline_id: 4, stage_id: 13, type_id: 1 },
  cold_email_nelson:      { source_id: 15, pipeline_id: 4, stage_id: 13, type_id: 1 },
  cold_email_vinoth:      { source_id: 16, pipeline_id: 4, stage_id: 13, type_id: 1 },
  apollo:                 { source_id: 17, pipeline_id: 4, stage_id: 13, type_id: 1 },
  referral:               { source_id: 18, pipeline_id: 4, stage_id: 13, type_id: 1 },
  whatsapp:               { source_id: 20, pipeline_id: 4, stage_id: 13, type_id: 1 },
};

const body = $input.first().json.body || $input.first().json;
const src = (body.source || 'contact_form').toLowerCase();
const route = SOURCE_MAP[src];
if (!route) {
  throw new Error(`unknown source: ${src}`);
}

if (!body.person || !body.person.email || !body.person.name) {
  throw new Error('person.name and person.email required');
}

const payload = {
  person: {
    name:      body.person.name,
    email:     body.person.email,
    phone:     body.person.phone || undefined,
    company:   body.person.company || undefined,
    job_title: body.person.job_title || undefined,
  },
  lead_pipeline_id:        route.pipeline_id,
  lead_pipeline_stage_id:  route.stage_id,
  lead_source_id:          route.source_id,
  lead_type_id:            route.type_id,
  title:                   body.title || `${src} — ${body.person.name}${body.person.company ? ' / ' + body.person.company : ''}`,
  description:             body.description || body.message || '',
  lead_value:              body.lead_value || undefined,
  activity_note:           body.activity_note || `Inbound via n8n (source=${src})`,
};

// Optional ICP segment from route map or explicit override
if (route.icp_segment_option_id || body.icp_segment_option_id) {
  payload.attributes = payload.attributes || {};
  payload.attributes.icp_segment = body.icp_segment_option_id || route.icp_segment_option_id;
}

// Optional scoped attributes from caller
if (body.attributes && typeof body.attributes === 'object') {
  payload.attributes = Object.assign(payload.attributes || {}, body.attributes);
}

return { payload, source: src, route };

// Merge Krayin response with the original payload context for downstream nodes.
const krayinResp = $input.first().json;
const ctx = $('Resolve route').first().json;
return {
  ok: !!krayinResp.success,
  lead_id: krayinResp.lead_id,
  person_id: krayinResp.person_id,
  source: ctx.source,
  payload: ctx.payload,
  krayin: krayinResp,
};
